+    pub fn deinit(self: *Self, allocator: std.mem.Allocator) void {
+        for (self.columns) |*col| col.deinit(allocator);
+        allocator.free(self.columns);
+        if (self.sorting_columns) |sc| allocator.free(sc);
+        self.* = .{};
